import os
import random
import struct
from typing import List

# This generator produces arbitrary binary blobs suitable as shard contents.
# Fuzzer stubs use FUZZ_PARAM_STR() to fill shard buffers of a chosen size (1..512).
# We generate diverse, valid contents that exercise different data patterns while
# remaining arbitrary binary data.

MAX_BLOCK = 512

def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))

def _pattern_zero(n: int) -> bytes:
    return b"\x00" * n

def _pattern_ff(n: int) -> bytes:
    return b"\xff" * n

def _pattern_inc(n: int, start: int = 0) -> bytes:
    return bytes((start + i) & 0xFF for i in range(n))

def _pattern_dec(n: int, start: int = 255) -> bytes:
    return bytes((start - i) & 0xFF for i in range(n))

def _pattern_stripes(n: int, period: int = 4) -> bytes:
    base = bytes([(i % period) * (255 // max(1, period - 1)) for i in range(period)])
    return (base * (n // period)) + base[: n % period]

def _pattern_sparse(n: int, step: int = 7, val: int = 0x80) -> bytes:
    # Mostly zeros with periodic non-zero to probe GF ops
    b = bytearray(n)
    for i in range(0, n, step):
        b[i] = val & 0xFF
    return bytes(b)

def _pattern_head_tail(n: int, head: bytes, tail: bytes) -> bytes:
    if n <= len(head) + len(tail):
        core = (head + tail)[:n]
        return core
    mid = n - len(head) - len(tail)
    return head + (b"\x00" * mid) + tail

def _mix_chunks(r: random.Random, n: int) -> bytes:
    # Concatenate small chunks of various patterns to create heterogeneity
    out = bytearray()
    patterns = [
        lambda m: _rand_bytes(r, m),
        _pattern_zero,
        _pattern_ff,
        _pattern_inc,
        _pattern_dec,
        _pattern_stripes,
        _pattern_sparse,
    ]
    while len(out) < n:
        remain = n - len(out)
        chunk = r.randint(1, min(64, remain))
        pat = r.choice(patterns)
        if pat in (_pattern_inc, _pattern_dec):
            start = r.randint(0, 255)
            out += pat(chunk, start)  # type: ignore[arg-type]
        elif pat is _pattern_stripes:
            period = r.randint(2, 16)
            out += _pattern_stripes(chunk, period)
        elif pat is _pattern_sparse:
            step = r.randint(3, 13)
            val = r.randint(1, 255)
            out += _pattern_sparse(chunk, step, val)
        else:
            out += pat(chunk)  # type: ignore[misc]
    return bytes(out[:n])

def _construct_blob(r: random.Random, size: int) -> bytes:
    # Choose a strategy to generate the blob
    choice = r.randint(0, 9)
    if choice == 0:
        return _pattern_zero(size)
    if choice == 1:
        return _pattern_ff(size)
    if choice == 2:
        return _pattern_inc(size, r.randint(0, 255))
    if choice == 3:
        return _pattern_dec(size, r.randint(0, 255))
    if choice == 4:
        period = r.randint(2, 32)
        return _pattern_stripes(size, period)
    if choice == 5:
        step = r.randint(3, 19)
        val = r.randint(1, 255)
        return _pattern_sparse(size, step, val)
    if choice == 6:
        head = struct.pack(
            ">IIBB", r.getrandbits(32), r.getrandbits(32), r.getrandbits(8), r.getrandbits(8)
        )
        tail = struct.pack(
            "<IHB", r.getrandbits(32), r.getrandbits(16), r.getrandbits(8)
        )
        return _pattern_head_tail(size, head, tail)
    if choice == 7:
        return _mix_chunks(r, size)
    if choice == 8:
        # Bias to small alphabet, good for GF linear dependencies
        alphabet = bytes(sorted(set(r.getrandbits(3) << 5 for _ in range(8))))
        return bytes(alphabet[r.randrange(len(alphabet))] for _ in range(size))
    # choice == 9
    return _rand_bytes(r, size)

def _choose_sizes(r: random.Random) -> List[int]:
    # The stubs independently choose sizes 1..512 per call; to be broadly useful,
    # we return a single buffer up to 4096 bytes containing concatenated blobs of
    # common shard sizes so multiple FUZZ_PARAM_STR() calls can slice from it.
    # However, since FUZZ_PARAM_STR reads the whole provided buffer, we focus on
    # producing a blob that is valid for any requested size by being sufficiently
    # random yet diverse. We'll pick a primary size in 64..512 with some bias.
    base = r.choice([64, 128, 192, 256, 320, 384, 448, 512])
    # Create a few segments that total up to <= 4096
    segments = r.randint(1, 6)
    sizes = []
    total = 0
    for _ in range(segments):
        s = r.randint(max(1, base // 2), base)
        if total + s > 4096:
            break
        sizes.append(s)
        total += s
    if not sizes:
        sizes = [min(base, 4096)]
    return sizes

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Compose multiple blobs back-to-back to give the fuzzer varied content
    sizes = _choose_sizes(r)
    chunks = []
    for sz in sizes:
        chunks.append(_construct_blob(r, sz))
    out = b"".join(chunks)
    # Ensure non-empty and <= 4096
    if not out:
        out = _rand_bytes(r, 64)
    return out[:4096]
